// G14 Track A (closes G13 limit §5-4 / review F04): SERVER-BACKED, single-use owner authorizations with a GLOBAL
// used-nonce store. The nonce is generated by the server (never taken from a client), the token is MACed with a key
// that exists only in this process (random at start, never persisted, never from the environment or a request), and
// it is valid only if THIS store issued it and has not seen it consumed. Consequences, by construction:
//   - a hand-made authorization object (the G13 gap) is refused: FORGED / UNKNOWN_TOKEN;
//   - a token can be consumed once, globally (every record, every action): NONCE_REUSED_GLOBAL;
//   - a restart invalidates every outstanding token (the key is gone), and the append-only journal of consumed nonces
//     keeps them refused afterwards even if the same nonce were ever presented again (defence in depth only: with a
//     per-process key a restart already makes every old token FORGED);
//   - a newer token for the same record + action revokes the older one (one open authorization at a time).
// It authorizes nothing by itself: the execution gate (server/gate.ts) stays CLOSED.
import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { canonicalJson } from "../../canonical";
import {
  authorizationProblem,
  issueAuthorization,
  type AuthorizedAction,
  type OwnerAuthorization,
} from "../../binding";

export interface AuthorizationToken extends OwnerAuthorization {
  chainId: string;
  mac: string;
}
export type TokenRefusal =
  | "TOKEN_MALFORMED"
  | "FORGED"
  | "UNKNOWN_TOKEN"
  | "REVOKED"
  | "NONCE_REUSED_GLOBAL"
  | "WRONG_CHAIN"
  | ReturnType<typeof authorizationProblem>;
export class TokenError extends Error {
  constructor(public code: NonNullable<TokenRefusal> | string) {
    super(code);
    this.name = "TokenError";
  }
}
/** Append-only persistence of consumed nonces (a file opened for append in production; memory in tests). */
export interface NonceJournal {
  append(line: string): void;
  load(): readonly string[];
}
export class MemoryNonceJournal implements NonceJournal {
  readonly #lines: string[] = [];
  append(line: string) {
    this.#lines.push(line);
  }
  load() {
    return [...this.#lines];
  }
}
const NONCE = /^[0-9a-f]{32}$/;
const MAC = /^[0-9a-f]{64}$/;
const fields = (t: Omit<AuthorizationToken, "mac">) =>
  canonicalJson([
    "veined.canary.authorization.v1",
    t.action,
    t.review,
    t.record,
    t.account.toLowerCase(),
    t.chainId,
    t.issuedAt,
    t.expiresAt,
    t.nonce,
  ]);

export class CanaryAuthorizationStore {
  readonly #key = randomBytes(32);
  readonly #used = new Set<string>();
  /** Outstanding tokens by nonce, and the open nonce per record+action. */
  readonly #issued = new Map<string, AuthorizationToken>();
  readonly #open = new Map<string, string>();
  readonly #journal: NonceJournal;
  constructor(journal: NonceJournal = new MemoryNonceJournal()) {
    this.#journal = journal;
    for (const line of journal.load())
      if (NONCE.test(line)) this.#used.add(line);
  }
  #mac(t: Omit<AuthorizationToken, "mac">) {
    return createHmac("sha256", this.#key).update(fields(t)).digest("hex");
  }
  /** Issued only for a real gesture, with enough quote time left (binding.ts rules), with a server nonce. */
  issue(i: {
    action: AuthorizedAction;
    review: string;
    record: string;
    account: string;
    chainId: string;
    now: number;
    quoteExpiresAt: number;
    trustedGesture: boolean;
    /** The token never outlives this instant (the engine passes quote expiry - minRemainingMs, review W1). */
    notAfter?: number;
  }): AuthorizationToken {
    // Expired outstanding tokens are dropped (round-1 review F15).
    for (const [n, t] of this.#issued)
      if (t.expiresAt <= i.now) {
        this.#issued.delete(n);
        if (this.#open.get(`${t.record}:${t.action}`) === n)
          this.#open.delete(`${t.record}:${t.action}`);
      }
    let nonce: string;
    do nonce = randomBytes(16).toString("hex");
    while (this.#used.has(nonce) || this.#issued.has(nonce));
    const issued = issueAuthorization({ ...i, nonce });
    const a =
      i.notAfter !== undefined && i.notAfter < issued.expiresAt
        ? { ...issued, expiresAt: i.notAfter }
        : issued;
    if (a.expiresAt <= i.now) throw new TokenError("AUTHORIZATION_EXPIRED");
    const body = { ...a, chainId: i.chainId };
    const token: AuthorizationToken = Object.freeze({
      ...body,
      mac: this.#mac(body),
    });
    const slot = `${i.record}:${i.action}`;
    const previous = this.#open.get(slot);
    if (previous) this.#issued.delete(previous);
    this.#open.set(slot, nonce);
    this.#issued.set(nonce, token);
    return token;
  }
  /**
   * Verifies and CONSUMES a token for exactly this record / review / action / account / chain, now. Returns the
   * OwnerAuthorization to hand to lifecycle.apply; any refusal throws TokenError and consumes nothing.
   */
  consume(
    token: unknown,
    expected: {
      action: AuthorizedAction;
      review: string;
      record: string;
      account: string;
      chainId: string;
      now: number;
    },
  ): OwnerAuthorization {
    if (!token || typeof token !== "object")
      throw new TokenError("TOKEN_MALFORMED");
    const t = token as Record<string, unknown>;
    const str = [
      "action",
      "review",
      "record",
      "account",
      "chainId",
      "nonce",
      "mac",
    ];
    if (
      str.some((k) => typeof t[k] !== "string") ||
      !Number.isSafeInteger(t.issuedAt) ||
      !Number.isSafeInteger(t.expiresAt)
    )
      throw new TokenError("TOKEN_MALFORMED");
    const tok = t as unknown as AuthorizationToken;
    if (!NONCE.test(tok.nonce) || !MAC.test(tok.mac))
      throw new TokenError("TOKEN_MALFORMED");
    const { mac, ...body } = tok;
    const want = Buffer.from(this.#mac(body), "hex");
    if (!timingSafeEqual(want, Buffer.from(mac, "hex")))
      throw new TokenError("FORGED");
    if (this.#used.has(tok.nonce)) throw new TokenError("NONCE_REUSED_GLOBAL");
    const known = this.#issued.get(tok.nonce);
    // A valid MAC means THIS process issued it; not outstanding and not consumed = superseded by a newer token.
    if (!known) throw new TokenError("REVOKED");
    if (known.mac !== mac) throw new TokenError("FORGED");
    if (tok.chainId !== expected.chainId) throw new TokenError("WRONG_CHAIN");
    const problem = authorizationProblem(tok, {
      ...expected,
      used: this.#used,
    });
    if (problem) throw new TokenError(problem);
    this.#journal.append(tok.nonce);
    this.#used.add(tok.nonce);
    this.#issued.delete(tok.nonce);
    this.#open.delete(`${tok.record}:${tok.action}`);
    return Object.freeze({
      action: tok.action,
      review: tok.review,
      record: tok.record,
      account: tok.account.toLowerCase(),
      issuedAt: tok.issuedAt,
      expiresAt: tok.expiresAt,
      nonce: tok.nonce,
    });
  }
  usedCount() {
    return this.#used.size;
  }
}
